import { defineTool } from "../../../tools.js";
import { cloudAgentsBackend } from "../lib/backend.js";
import { assertWriteChannel } from "../lib/channels.js";
import { assertOwned } from "../lib/fleet.js";
import { agentRef } from "../lib/inputs.js";
import { disarmWatches } from "../lib/watch.js";
const cancel = defineTool({
    description: "Stop a cloud agent's active run; no stop wake follows. The agent keeps its branch and conversation; reply to it to continue.",
    effect: "write",
    inputSchema: agentRef,
    async execute(input, ctx) {
        assertWriteChannel(ctx);
        await assertOwned(ctx, input.agent_id);
        await cloudAgentsBackend().pause(input.agent_id);
        await disarmWatches(ctx, input.agent_id);
        return { agentId: input.agent_id, cancelled: true };
    },
});
export default cancel;
